const customer = ($('AlfaCRM: Fetch Lead Card').item.json.items || [{}])[0];
const rows = items.map(i => i.json.message).reverse();

const dialog = rows.map(m => {
  try {
    const obj = typeof m === 'string' ? JSON.parse(m) : m;
    const role = obj.type === 'human' ? '👤' : '🤖';
    const text = (obj.data?.content || '').slice(0, 200);
    return `${role} ${text}`;
  } catch { return ''; }
}).filter(Boolean).join('\n');

const input = $('When Called by Main').item.json;
const dl = `https://${$env.ALFACRM_HOSTNAME}/index.php?route=client/index&id=${input.customerId}`;

const text = [
  `🔥 *ГОРЯЧИЙ ЛИД — забери в работу*`,
  ``,
  `*Имя:* ${customer.name || '?'}`,
  `*Телефон:* ${input.phone}`,
  `*Этап:* ${customer.lead_status_id || '?'} → 4 (горячий)`,
  `*Источник:* ${customer.lead_source_id || '?'}`,
  ``,
  `*Причина квалификации:* ${input.reason}`,
  ``,
  `*Последние сообщения:*`,
  '```',
  dialog || '(нет истории)',
  '```',
  ``,
  `[Открыть в AlfaCRM](${dl})`
].join('\n');

return [{
  json: {
    chat_id: $env.TELEGRAM_SALES_CHAT_ID,
    text,
    parse_mode: 'Markdown',
    reply_markup: {
      inline_keyboard: [[
        { text: '✅ Взять в работу', callback_data: `take:${input.customerId}` },
        { text: '👁 Открыть AlfaCRM', url: dl }
      ]]
    }
  }
}];
